"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["1338"],{51219(e){e.exports=JSON.parse('{"id":"FIN-027","slug":"financial-literacy","term":"Financial Literacy","also_known_as":[],"difficulty":"Beginner","definition":"Financial literacy is the knowledge and skill needed to make sound decisions about money, such as budgeting, saving, borrowing, investing and understanding risk.","explanation":["Financial literacy is not about being an expert. It means understanding enough to manage everyday money well and to avoid costly mistakes. It includes knowing how interest works, how to read a loan offer, why diversification reduces risk and how inflation affects savings.","The difference it makes can be large. Someone who understands that a credit card charging 24% a year costs far more than a loan at 8% is less likely to carry expensive debt. Someone who understands compound interest is more likely to start saving early.","Financial literacy also helps people recognise scams and unsuitable products. Offers that promise high returns with no risk, or loans with hidden fees, are easier to spot when you understand the basics.","Surveys in many countries show that large numbers of adults struggle with basic questions about interest, inflation and risk. This is why governments, schools and employers increasingly offer financial education, and why clear, plain-language resources matter."],"note":"","total":1500,"prev":{"slug":"financial-leverage","term":"Financial Leverage"},"next":{"slug":"financial-management","term":"Financial Management"}}')}}]);